import{_ as a,c as n,o,a2 as i}from"./chunks/framework.mqLGQ42V.js";const b=JSON.parse('{"title":"骨骼 (Bones) - Rive 编辑器","description":"操控形状 (Manipulating Shapes) 骨骼允许你为图稿创建骨架。这是一种直观自然的方式，用于动画化多个相互连接的部位，例如手臂、旗帜或树枝。","frontmatter":{"title":"骨骼 (Bones) - Rive 编辑器","description":"操控形状 (Manipulating Shapes) 骨骼允许你为图稿创建骨架。这是一种直观自然的方式，用于动画化多个相互连接的部位，例如手臂、旗帜或树枝。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 形状操控, 骨骼"}]]},"headers":[],"relativePath":"editor/manipulating-shapes/bones.md","filePath":"editor/manipulating-shapes/bones.md","lastUpdated":1774838907000}'),t={name:"editor/manipulating-shapes/bones.md"};function r(s,e,p,h,d,c){return o(),n("div",null,[...e[0]||(e[0]=[i('<p>操控形状 (Manipulating Shapes)</p><h1 id="骨骼-bones" tabindex="-1">骨骼 (Bones) <a class="header-anchor" href="#骨骼-bones" aria-label="Permalink to &quot;骨骼 (Bones)&quot;">​</a></h1><p>骨骼允许你为图稿创建骨架。这是一种直观自然的方式，用于动画化多个相互连接的部位，例如手臂、旗帜或树枝。</p><h2 id="​-创建骨骼-creating-bones" tabindex="-1"><a href="#creating-bones">​</a> 创建骨骼 (Creating Bones) <a class="header-anchor" href="#​-创建骨骼-creating-bones" aria-label="Permalink to &quot;[​](#creating-bones) 创建骨骼 (Creating Bones)&quot;">​</a></h2><p>要创建骨骼，请从工具栏中选择<strong>骨骼工具 (Bone Tool)</strong>，或按快捷键 <code>B</code>。激活工具后，在画板上点击并拖动，绘制出第一根骨骼。松开鼠标确认第一根骨骼后，可以继续拖动来创建子骨骼，形成完整的骨骼链。</p><p>要回到父级骨骼，请按 <code>Esc</code> 键。要在其它骨骼下创建兄弟骨骼，请在层级面板中选中目标骨骼并重新绘制。</p><h2 id="​-绑定骨骼-binding-bones" tabindex="-1"><a href="#binding-bones">​</a> 绑定骨骼 (Binding Bones) <a class="header-anchor" href="#​-绑定骨骼-binding-bones" aria-label="Permalink to &quot;[​](#binding-bones) 绑定骨骼 (Binding Bones)&quot;">​</a></h2><p>骨骼创建后需要与形状或网格关联。将形状拖放到骨骼下方，使其成为子级，骨骼的变换就会继承给形状。</p><p>对于更复杂的变形，可以为形状添加<strong>网格 (Mesh)</strong>，然后使用权重工具（Weight Tool）将骨骼绑定到网格的特定顶点上。这让你能实现柔软、有机的弯曲效果（如角色身体或飘动的布料）。</p><h2 id="​-骨骼层级-bone-hierarchy" tabindex="-1"><a href="#bone-hierarchy">​</a> 骨骼层级 (Bone Hierarchy) <a class="header-anchor" href="#​-骨骼层级-bone-hierarchy" aria-label="Permalink to &quot;[​](#bone-hierarchy) 骨骼层级 (Bone Hierarchy)&quot;">​</a></h2><p>骨骼天然具有父子层级结构。移动父骨骼时，其所有子骨骼会一同跟随。这种&quot;前向运动学 (Forward Kinematics, FK)&quot;是理解骨骼动画的基础。</p><p>如果你希望通过移动链条的末端来反推整个链条的姿态（例如抓取物体时手的位置驱动手臂），可以使用<strong>反向动力学约束 (IK Constraint)</strong>。</p><p><a href="/docs/editor/manipulating-shapes/clipping">裁剪 (Clipping)</a><a href="/docs/editor/manipulating-shapes/bone-tips">骨骼技巧 (Bone Tips)</a></p>',13)])])}const g=a(t,[["render",r]]);export{b as __pageData,g as default};
